const crypto = require("crypto");

const body = $json.body ?? $json;
const initData = typeof body.initData === "string" ? body.initData.trim() : "";
const botToken = String(
  $vars.TELEGRAM_BOT_TOKEN
  ?? $env.TELEGRAM_BOT_TOKEN
  ?? "",
).trim();

if (!botToken) {
  throw new Error("Falta configurar TELEGRAM_BOT_TOKEN en n8n.");
}

function invalid() {
  return [{
    json: {
      valid: false,
      mode: "public",
    },
  }];
}

if (!initData) return invalid();

const params = new URLSearchParams(initData);
const receivedHash = params.get("hash") ?? "";
const authDate = Number(params.get("auth_date"));

if (!receivedHash || !Number.isInteger(authDate)) return invalid();

const now = Math.floor(Date.now() / 1000);
const isFuture = authDate > now + 60;
const isExpired = now - authDate > 86400;
if (isFuture || isExpired) return invalid();

const dataCheckString = [...params.entries()]
  .filter(([key]) => key !== "hash")
  .sort(([keyA], [keyB]) => keyA.localeCompare(keyB))
  .map(([key, value]) => `${key}=${value}`)
  .join("\n");

const secretKey = crypto
  .createHmac("sha256", "WebAppData")
  .update(botToken)
  .digest();
const expectedHash = crypto
  .createHmac("sha256", secretKey)
  .update(dataCheckString)
  .digest("hex");

const received = Buffer.from(receivedHash, "hex");
const expected = Buffer.from(expectedHash, "hex");
const hashesMatch = received.length === expected.length
  && crypto.timingSafeEqual(received, expected);

if (!hashesMatch) return invalid();

let user;
try {
  user = JSON.parse(params.get("user") ?? "{}");
} catch {
  return invalid();
}

if (!user || !Number.isSafeInteger(user.id)) return invalid();

return [{
  json: {
    valid: true,
    telegram_id: String(user.id),
    first_name: typeof user.first_name === "string" ? user.first_name : "",
    username: typeof user.username === "string" ? user.username : null,
  },
}];
